package calc

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"

	"ragnarok-of-building/internal/gamedata"
)

// LATAM skill formulas.
//
// The formulas themselves live in latam_gen.go, generated by tools/latamgen
// from latam-ro-calc (Adson Leal, MIT License,
// https://github.com/adsonpleal/latam-ro-calc), which measured them against
// real LATAM recordings. This file is the runtime they need: the formula
// input, the per-class registry and the helpers the generated code calls.

// FormulaInput is what a skill formula can read.
type FormulaInput struct {
	Lv           int // skill level used
	BaseLv       int
	JobLv        int
	Stats        [6]int // final STR..LUK
	Traits       [6]int // final POW..CRT
	HIT, FLEE    int
	CRIT         float64
	ASPD         int
	Learned      map[int]int
	Catalog      *gamedata.Catalog
	Monster      *gamedata.Monster
	Weapon       string // weapon type (rAthena SubType), "Fist" when none
	WeaponLv     int
	WeaponWt     int // weapon weight (rAthena, tenths)
	WeaponRefine int
	ShieldWt     int // shield weight (tenths); 0 without a shield
	ShieldRefine int
	WeaponATK    int
	MaxHP        int
	MaxSP        int
	States       map[string]int
	Stack        int
}

// S and T return final stats and traits as float64 (formula arithmetic).
func (in FormulaInput) S(i int) float64 { return float64(in.Stats[i]) }
func (in FormulaInput) T(i int) float64 { return float64(in.Traits[i]) }

// LearnLv returns the learned level of a skill by client code.
func (in FormulaInput) LearnLv(code string) int {
	if in.Catalog == nil {
		return 0
	}
	for id, lv := range in.Learned {
		if sk := in.Catalog.Skills[id]; sk != nil && sk.Code == code {
			return lv
		}
	}
	return 0
}

// LearnName returns the learned level of a skill by English name (as the
// formulas name them).
func (in FormulaInput) LearnName(name string) int {
	if in.Catalog == nil {
		return 0
	}
	want := normName(name)
	for id, lv := range in.Learned {
		if sk := in.Catalog.Skills[id]; sk != nil && normName(sk.Name["en"]) == want {
			return lv
		}
	}
	return 0
}

// Active reports whether a state/buff toggle (named after its skill) is on.
func (in FormulaInput) Active(name string) bool { return in.States[stateKey(name)] != 0 }

// ActiveLv returns the level chosen for a leveled state (e.g. stacks, spins).
func (in FormulaInput) ActiveLv(name string) int { return in.States[stateKey(name)] }

// CelestialSpace reports whether the Sky Emperor space is active (Unity counts as all).
func (in FormulaInput) CelestialSpace(space int) bool {
	s := in.ActiveLv("_SkyEmperor_Celestial_Space")
	return s == space || s == 7
}

// Mon returns a monster attribute in latam-ro-calc's lowercase naming.
func (in FormulaInput) Mon(attr string) string {
	if in.Monster == nil {
		return ""
	}
	switch attr {
	case "race":
		return strings.ToLower(in.Monster.Race)
	case "element":
		return strings.ToLower(in.Monster.Element)
	case "size":
		return strings.ToLower(in.Monster.Size)
	case "type":
		if in.Monster.Class == "Boss" {
			return "boss"
		}
		return "normal"
	}
	return ""
}

// MonNum returns a numeric monster attribute.
func (in FormulaInput) MonNum(attr string) float64 {
	m := in.Monster
	if m == nil {
		return 0
	}
	switch attr {
	case "hp":
		return float64(m.HP)
	case "level":
		return float64(m.Level)
	case "def":
		return float64(m.DEF)
	case "mdef":
		return float64(m.MDEF)
	case "res":
		return float64(m.RES)
	case "mres":
		return float64(m.MRES)
	}
	return 0
}

// MonIs checks race/element/size/type against any of the given names.
func (in FormulaInput) MonIs(attr string, names ...string) bool {
	v := in.Mon(attr)
	for _, n := range names {
		if strings.EqualFold(n, v) {
			return true
		}
	}
	return false
}

// WeaponIs reports whether the weapon is one of the rAthena SubTypes given.
func (in FormulaInput) WeaponIs(types ...string) bool {
	for _, t := range types {
		if t == in.Weapon {
			return true
		}
	}
	return false
}

var weaponNames = map[string]string{
	"Dagger": "dagger", "1hSword": "sword", "2hSword": "twohandSword", "1hSpear": "spear",
	"2hSpear": "twohandSpear", "1hAxe": "axe", "2hAxe": "twohandAxe", "Mace": "mace",
	"2hMace": "twohandMace", "Staff": "rod", "2hStaff": "twohandRod", "Bow": "bow",
	"Knuckle": "knuckle", "Musical": "instrument", "Whip": "whip", "Book": "book",
	"Katar": "katar", "Revolver": "pistol", "Rifle": "rifle", "Gatling": "gatlingGun",
	"Shotgun": "shotgun", "Grenade": "grenadeLauncher", "Huuma": "huuma",
}

// WeaponName returns the weapon type in latam-ro-calc's naming.
func (in FormulaInput) WeaponName() string { return weaponNames[in.Weapon] }

// StateOption is a toggle/selector the damage window shows for a class.
type StateOption struct {
	Key     string
	Label   string
	Choices [][2]string // value, label; empty = on/off checkbox
}

// SkillFormula is a LATAM damage formula for one skill.
type SkillFormula struct {
	Code          string
	Name          string                     // latam-ro-calc's name
	Ratio         func(FormulaInput) float64 // % of ATK/MATK, total for one use
	Magic         bool                       // MATK-based (magic pipeline)
	Element       string                     // fixed element ("" = weapon/endow)
	Hits          func(FormulaInput) int     // real damage multiplier (totalHit); nil = 1
	CanCrit       func(FormulaInput) bool    // nil = no crits
	CritRate      float64                    // fraction of the crit chance (baseCriPercentage)
	CritDmg       float64                    // fraction of the crit damage bonus (criDmgPercentage)
	ForceCrit     bool
	IgnoreDef     bool
	IgnoreSoftDef bool
	IgnoreRes     bool
	Hit100        bool                    // never misses (latam-ro-calc isHit100)
	Melee         func(FormulaInput) bool // nil = by weapon (ranged weapons are long range)
	Weapons       []string                // required weapon types (rAthena SubType); empty = any
	RequiresState string                  // state that must be on (e.g. an aura)
	Stack         [2]int                  // min,max stacks when the skill uses them
	Partial       string                  // parts of the skill not simulated
	Rebalanced    bool                    // formula from the 2022 rebalance (LATAM "current")
	Variant       string                  // label of this variant ("Calafrio", "Explosão"...)
	Alts          []*SkillFormula         // further variants of the same skill
	Source        string                  // "" = latam-ro-calc; "bROWiki" when corrected from it
}

var (
	latamByJob  = map[string]map[string]*SkillFormula{} // job code -> skill code -> formula
	latamStates = map[string][]StateOption{}
	nonWord     = regexp.MustCompile(`[^a-z0-9]+`)
)

func regJob(job string, f *SkillFormula) {
	if f.CritRate == 0 {
		f.CritRate = 1
	}
	if f.CritDmg == 0 {
		f.CritDmg = 1
	}
	if latamByJob[job] == nil {
		latamByJob[job] = map[string]*SkillFormula{}
	}
	if first := latamByJob[job][f.Code]; first != nil {
		if first.Variant == "" {
			first.Variant = "Normal"
		}
		if f.Variant == "" {
			f.Variant = fmt.Sprintf("Variante %d", len(first.Alts)+2)
		}
		first.Alts = append(first.Alts, f)
		return
	}
	latamByJob[job][f.Code] = f
}

// Variants lists a formula and its alternatives (nil-safe).
func (f *SkillFormula) Variants() []*SkillFormula {
	if f == nil {
		return nil
	}
	return append([]*SkillFormula{f}, f.Alts...)
}

// Pick returns variant i (0 = the first), or the first when out of range.
func (f *SkillFormula) Pick(i int) *SkillFormula {
	if f == nil || i <= 0 || i > len(f.Alts) {
		return f
	}
	return f.Alts[i-1]
}

func regStates(job string, opts []StateOption) { latamStates[job] = append(latamStates[job], opts...) }

func normName(s string) string { return nonWord.ReplaceAllString(strings.ToLower(s), "") }

func stateKey(name string) string { return "s_" + normName(name) }

func levelChoices(n int) [][2]string {
	out := [][2]string{{"0", "—"}}
	for i := 1; i <= n; i++ {
		out = append(out, [2]string{strconv.Itoa(i), strconv.Itoa(i)})
	}
	return out
}

// FormulaFor finds the LATAM formula for a skill as used by a job: the
// job's own class file first, then its ancestors' (a Dragon Knight's Dragon
// Breath is not a Rune Knight's).
func FormulaFor(c *gamedata.Catalog, jobID int, code string) *SkillFormula {
	chain := c.Chain(jobID)
	for i := len(chain) - 1; i >= 0; i-- {
		if j := c.Jobs[chain[i]]; j != nil {
			if f := latamByJob[j.Code][code]; f != nil {
				return f
			}
		}
	}
	return nil
}

// StatesFor lists the state selectors for a job and its ancestors.
func StatesFor(c *gamedata.Catalog, jobID int) []StateOption {
	var out []StateOption
	seen := map[string]bool{}
	chain := c.Chain(jobID)
	for i := len(chain) - 1; i >= 0; i-- {
		j := c.Jobs[chain[i]]
		if j == nil {
			continue
		}
		for _, o := range latamStates[j.Code] {
			if !seen[o.Key] {
				seen[o.Key] = true
				out = append(out, o)
			}
		}
	}
	return out
}

// ---- helpers used by the generated formulas (JavaScript semantics) ----

func always(FormulaInput) bool      { return true }
func meleeAlways(FormulaInput) bool { return true }
func meleeNever(FormulaInput) bool  { return false }
func constHits(n int) func(FormulaInput) int {
	return func(FormulaInput) int { return n }
}

func b2f(b bool) float64 {
	if b {
		return 1
	}
	return 0
}

func tern(c bool, a, b float64) float64 {
	if c {
		return a
	}
	return b
}

func ternB(c, a, b bool) bool {
	if c {
		return a
	}
	return b
}

func ternS(c bool, a, b string) string {
	if c {
		return a
	}
	return b
}

func orNum(a, b float64) float64 { // a || b
	if a != 0 {
		return a
	}
	return b
}

func andNum(a, b float64) float64 { // a && b
	if a == 0 {
		return a
	}
	return b
}

func strEq(a, b string) bool { return strings.EqualFold(a, b) }

func idx(arr []float64, i float64) float64 { // out of range is undefined in JS: 0 here
	n := int(i)
	if n < 0 || n >= len(arr) {
		return 0
	}
	return arr[n]
}

func fmin(v ...float64) float64 {
	m := math.Inf(1)
	for _, x := range v {
		m = math.Min(m, x)
	}
	return m
}

func fmax(v ...float64) float64 {
	m := math.Inf(-1)
	for _, x := range v {
		m = math.Max(m, x)
	}
	return m
}

func jsRound(x float64) float64 { return math.Floor(x + 0.5) } // Math.round

// ratioFloor applies a percentage ratio with LATAM's flooring.
func ratioFloor(v int64, pct float64) int64 { return int64(math.Floor(float64(v) * pct / 100)) }

// Choice reports whether an exclusive selector (e.g. the active elemental
// spirit) is set to the given option.
func (in FormulaInput) Choice(group string, option int) bool { return in.States["c_"+group] == option }

func containsF(arr []float64, v float64) bool { // [..].includes(v)
	for _, x := range arr {
		if x == v {
			return true
		}
	}
	return false
}

// MonStat returns the target's base stat (STR..LUK index), 0 without a target.
func (in FormulaInput) MonStat(i int) float64 {
	if in.Monster == nil || i < 0 || i >= len(in.Monster.Stats) {
		return 0
	}
	return float64(in.Monster.Stats[i])
}
